results.pipeline_sql:
SELECT AVG(explainability_score) AS avg_explainability_score 
FROM creative_ai 
WHERE region IN ('Europe', 'North America');

SELECT AVG(publications) AS average_publications 
FROM researchers 
WHERE organization = 'National Geographic';

SELECT COUNT(*) AS num_public_works, AVG(resilience_score) AS avg_resilience_score 
FROM Infrastructure 
WHERE location = 'California' AND is_public_works = TRUE;

SELECT SongName, Genre, Streams 
FROM Music 
ORDER BY Streams DESC LIMIT 1;
SELECT SongName, Genre, Streams 
FROM Music 
ORDER BY Streams ASC LIMIT 1;

SELECT AVG(obesityrate) AS AverageObesityRate 
FROM ObesityRates 
WHERE continent = 'North America' AND year = 2019;

SELECT funding_source_type, COUNT(*) as number_of_funding_sources, (COUNT(*) * 100.0 / SUM(COUNT(*)) OVER()) as distribution_percentage 
FROM funding_sources 
GROUP BY funding_source_type;

SELECT operation_name, environmental_impact 
FROM mining_operations 
WHERE environmental_impact > (SELECT AVG(environmental_impact) FROM mining_operations);

SELECT SUM(CASE WHEN launch_country = 'Japan' THEN 1 ELSE 0 END) + 
       SUM(CASE WHEN launch_country = 'USA' THEN 1 ELSE 0 END) AS total_missions
FROM space_missions;

SELECT AVG(precipitation) AS avg_precipitation 
FROM weather_data_2022 
WHERE crop_type = 'Wheat' AND location = 'France';

SELECT ((SUM(CASE WHEN date = '2022-04-01' THEN number_of_tourists ELSE 0 END) - SUM(CASE WHEN date = '2022-03-01' THEN number_of_tourists ELSE 0 END)) / SUM(CASE WHEN date = '2022-03-01' THEN number_of_tourists ELSE 0 END)) * 100 AS percentage_change
FROM tourism
WHERE host_country = 'Japan' AND visitor_country = 'India';

SELECT author_id, region_id, COUNT(*) as total_articles 
FROM articles 
GROUP BY author_id, region_id;

SELECT AVG(CASE WHEN Cases.outcome = 'won' THEN 1.0 ELSE 0.0 END) AS success_rate 
FROM Cases 
INNER JOIN Attorneys ON Attorneys.AttorneyID = Cases.CaseID;

SELECT AVG(financial_wellbeing_score) 
FROM shariah_compliant_customers 
WHERE wellbeing_assessment_date BETWEEN '2022-04-01' AND '2022-06-30';

SELECT state, COUNT(DISTINCT worker_id) * 100.0 / COUNT(worker_id) AS percentage_speaking_spanish 
FROM community_health_workers_lang 
GROUP BY state;

SELECT COUNT(*) 
FROM volunteers_ext 
WHERE assignment_date < (SELECT MIN(assignment_date) FROM volunteers_ext WHERE skill = 'Engineering') AND skill = 'Medical';

SELECT program_id, AVG(donation_amount) AS avg_donation, COUNT(donation_id) AS donation_count 
FROM donations 
GROUP BY program_id;

SELECT MIN(recycling_rate) AS min_glass_recycling_rate 
FROM RecyclingRates 
WHERE year = 2019 AND region IN ('South America', 'Africa');

SELECT project_name, completion_date 
FROM rural_infrastructure 
WHERE completion_date < '2020-01-01';

SELECT SUM(energy_produced) AS total_energy_produced
FROM renewable_energy
WHERE country = 'Germany' AND year = 2020;

SELECT 100.0 * COUNT(*) / (SELECT COUNT(*) FROM hotel_features WHERE country IN ('France', 'Germany', 'Italy', 'Spain')) AS percentage
FROM hotel_features
WHERE country IN ('France', 'Germany', 'Italy', 'Spain') AND virtual_tour = 1;

SELECT SUM(program_id) AS total_programs_in_texas_and_california 
FROM community_ed 
WHERE location IN ('Texas', 'California');

SELECT vehicle_type, MAX(trip_distance) as max_distance 
FROM trips 
GROUP BY vehicle_type;

SELECT publish_date, SUM(word_count) AS total_word_count 
FROM News 
GROUP BY publish_date;

SELECT DISTINCT country 
FROM eu_peacekeeping_operations 
WHERE strftime('%Y', start_date) = '2010';
